def register(add):
    add("T085", title="io.Reader / io.Writer 抽象", level="intermediate", kind="single-file", runtime="desktop",
        files=["main.go"], codeFile="main.go", vkind="stdout-exact",
        expected="copied bytes: 16 err: <nil>\nbuffer content: hello, io.Reader\ncustom reader: ababab", run="go run main.go",
        concepts=["io.Reader", "io.Writer", "io.Copy", "自定义 Reader"],
        summary="围绕 io.Reader/io.Writer 接口组合来源与目标，并实现一个自定义 Reader。",
        objective="能基于 io.Reader/Writer 编写与来源无关的代码，并实现自定义 Reader。",
        prereq=["T041 接口基础与鸭子类型", "T030 指针二：指针与切片/映射的关系"],
        pitfalls=["自定义 Read 用值接收者：无法推进读取位置，导致死循环或重复读（本示例曾因此 OOM）。", "忽略 Read 的 n 与 err：必须同时处理“读了多少”和“是否结束”。"],
        exercises=[{"prompt": "实现一个 upperReader，把底层 Reader 的字节转成大写输出。", "hint": "包装一个 io.Reader，Read 后对读到的 n 个字节做大写转换。", "answer": "Read 委托底层后 for i:=0;i<n;i++ { p[i]=toUpper(p[i]) }。"}],
        explain="io.Reader 只有 Read([]byte) (int, error)，io.Writer 只有 Write([]byte) (int, error)。任何实现了它们的东西都能互相组合：字符串、文件、网络、内存缓冲。示例把 strings.Reader 当来源、bytes.Buffer 当目标，用 io.Copy 搬运，代码完全无需知道底层类型。随后实现 repeatReader：它把固定字节重复若干次——这里必须用指针接收者，因为要在 Read 中推进 pos；用值接收者会让 pos 永不前进，引发无限读取（本示例开发时就踩过这个坑，真实运行暴露后修正）。这就是“自定义接口实现”与接收者选择的实战意义。")
    add("T086", title="文件读写：os.Open/Create 与缓冲", level="intermediate", kind="single-file", runtime="desktop",
        files=["main.go"], codeFile="main.go", vkind="stdout-exact",
        expected="read back:\nline one\nline two\nsize matches: true", run="go run main.go",
        concepts=["os.Create", "os.ReadFile", "Close", "临时目录"],
        summary="在临时目录安全创建、写入、关闭、读回文件，并校验字节数。",
        objective="能正确打开/写入/关闭并读回文件，说明写后 Close 的必要性。",
        prereq=["T085 io.Reader / io.Writer 抽象"],
        pitfalls=["写后不 Close：数据可能未落盘，且句柄泄漏。", "在仓库工作目录写文件：污染工作区；应用 os.MkdirTemp 并 defer RemoveAll。"],
        exercises=[{"prompt": "把内容按行追加到文件而非覆盖，并读回验证行数。", "hint": "用 os.OpenFile 带 os.O_APPEND。", "answer": "os.OpenFile(path, os.O_APPEND|os.O_WRONLY|os.O_CREATE, 0o644)。"}],
        explain="文件读写是 IO 的常见场景。示例先用 os.MkdirTemp 建立隔离的临时目录并 defer RemoveAll，避免污染工作目录；再用 os.Create 写入内容，随后 Close——Close 不仅释放句柄，也保证缓冲数据落盘。读回用 os.ReadFile 一次性读入，并用 os.Stat 校验字节数，作为确定性断言。这些习惯（隔离目录、及时关闭、校验结果）是可重复、可测试文件操作的基础。移动端文件系统能力未实测，标 Yaegi*（待实测），默认 desktop。")
    add("T087", title="bufio：按行/按词扫描与缓冲写", level="intermediate", kind="single-file", runtime="desktop",
        files=["main.go"], codeFile="main.go", vkind="stdout-exact",
        expected="line 1: go is fun\nline 2: bufio scans lines\nline 3: and words too\ntotal lines: 3\ntotal words: 9", run="go run main.go",
        concepts=["bufio.Scanner", "按行", "按词", "缓冲"],
        summary="用 bufio.Scanner 按行与按词两种方式扫描文本并统计。",
        objective="能用 bufio.Scanner 处理文本，说明默认行上限与如何调大。",
        prereq=["T085 io.Reader / io.Writer 抽象"],
        pitfalls=["超长行（>64KB）未调大 Buffer：Scan 会因 token too long 返回 false，容易误判为 EOF。", "忘记检查 Scanner.Err()：扫描中途的 IO 错误会被漏掉。"],
        exercises=[{"prompt": "统计每行单词数并打印行号。", "hint": "对每行再用 strings.Fields 分词。", "answer": "for lineScan.Scan() { n := len(strings.Fields(lineScan.Text())); ... }"}],
        explain="bufio.Scanner 把 Reader 包装成“按 token”迭器，默认按行切分，也可用 Split(bufio.ScanWords) 按词。它内部带缓冲，减少系统调用。示例对同一段文本先按行、再按词扫描并打印统计，输出确定。注意两个要点：一是默认单行上限约 64KB，超长行需要 scan.Buffer(make([]byte, 0, max), max) 调大；二是循环结束后应检查 scan.Err()，否则扫描中途的 IO 错误会被静默忽略。")
    add("T088", title="目录遍历与文件信息", level="intermediate", kind="single-file", runtime="desktop",
        files=["main.go"], codeFile="main.go", vkind="stdout-exact",
        expected="alpha.txt  file size=1\nbeta.txt   file size=2\nsub        dir", run="go run main.go",
        concepts=["os.ReadDir", "FileInfo", "排序", "目录"],
        summary="用 os.ReadDir 列出目录条目（已排序）并用 FileInfo 读取元数据。",
        objective="能用 os.ReadDir 遍历目录并判断条目是否为目录、读取大小等元数据。",
        prereq=["T086 文件读写：os.Open/Create 与缓冲"],
        pitfalls=["依赖目录原始顺序：不同文件系统顺序不同，ReadDir 已按名字排序，应利用这一点。", "对符号链接用 Info 判断类型会得到目标信息：需用 Lstat 或 DirEntry.Type 区分。"],
        exercises=[{"prompt": "实现一个只列 .txt 文件的函数，返回按大小排序的文件名。", "hint": "先 ReadDir 过滤后缀，再按 Info().Size() 排序。", "answer": "过滤 strings.HasSuffix(name,\".txt\")，收集 (name,size) 后排序输出。"}],
        explain="os.ReadDir 返回目录条目切片，并保证按文件名排序，因此遍历输出天然确定——这是构建可复现输出的关键。每个 DirEntry 可通过 Info() 拿到 FileInfo（大小、模式等），IsDir() 判断是否为目录。示例在临时目录建两个文件和一个子目录，然后列出并按“名字 + 类型 + 大小”打印，输出稳定。移动端目录访问能力未实测，标 Yaegi*（待实测），默认 desktop。")
    add("T089", title="JSON 一：Marshal/Unmarshal 基础", level="intermediate", kind="single-file", runtime="desktop",
        files=["main.go"], codeFile="main.go", vkind="stdout-exact",
        expected='marshal: {"name":"gopher","age":15,"hobbies":["coding","reading"]}\nunmarshal name: gopher\nunmarshal age: 15\nunmarshal hobbies: [coding reading]\nround-trip stable: true', run="go run main.go",
        concepts=["encoding/json", "Marshal", "Unmarshal", "往返"],
        summary="用 json.Marshal/Unmarshal 在结构体与 JSON 之间往返转换。",
        objective="能用 Marshal/Unmarshal 编解码结构体，并说明导出字段才被编码。",
        prereq=["T037 结构体定义、字面量与字段访问"],
        pitfalls=["字段未导出（小写）：不会被编码，产出为空对象。", "Unmarshal 传入非指针：无法写回，报错或静默无效果。"],
        exercises=[{"prompt": "给 Profile 增加一个 []int 字段并验证往返一致。", "hint": "切片字段也要导出并带 tag。", "answer": "加 Scores []int `json:\"scores\"`；重新 Marshal/Unmarshal 比较。"}],
        explain="encoding/json 是 Go 与 JSON 互转的标准方式。Marshal 把 Go 值编码为 JSON 字节切片，Unmarshal 把 JSON 解析回指定类型（需传指针）。结构体字段必须导出（首字母大写）才会参与编码，否则被忽略。示例对 Profile 做往返：编码得到 JSON，再解码回结构体，并比较再次编码结果是否稳定，作为确定性断言。这类往返不变性是验证编解码正确性的常用手段。")
    add("T090", title="JSON 二：struct tag、omitempty 与自定义名称", level="intermediate", kind="single-file", runtime="desktop",
        files=["main.go"], codeFile="main.go", vkind="stdout-exact",
        expected='minimal: {"id":7,"name":"alice","balance":0}\nfilled:  {"id":7,"name":"alice","email":"alice@example.com","nick_name":"ali","balance":100}\npassword hidden: true', run="go run main.go",
        concepts=["struct tag", "omitempty", "忽略字段", "字段改名"],
        summary="用 struct tag 控制 JSON 键名、省略空值与完全忽略字段。",
        objective="能用 tag 控制字段名、用 omitempty 省略零值、用 \"-\" 屏蔽敏感字段。",
        prereq=["T089 JSON 一：Marshal/Unmarshal 基础"],
        pitfalls=["对结构体/切片用 omitempty：只有在 nil/空时省略，非空零值结构体不会被省略。", "以为 tag 里的名字会影响 Go 字段访问：tag 只影响（反）序列化，字段名不变。"],
        exercises=[{"prompt": "为 Account 增加 UpdatedAt time.Time 字段，用字符串格式输出。", "hint": "自定义 MarshalJSON 或改字段为 string。", "answer": "改字段为 string 并赋 RFC3339 值，或实现 MarshalJSON 定制输出。"}],
        explain="struct tag 是反引号里的元数据，encoding/json 读取其中 json:\"...\" 部分：\"name\" 改键名、\"omitempty\" 在零值时省略、\"-\" 表示完全不序列化。示例的 Account 演示三者：Password 带 `json:\"-\"` 永不出现（即使非空），Email/Nickname 用 omitempty 仅在非空时出现，并提供 Password 确实被隐藏的断言。理解 tag 的边界很重要：它只影响序列化视角，不改变 Go 层字段名与可见性。")
